import math
import re


def parse_duration(text):
    if not isinstance(text, str):
        raise ValueError("duration must be a string")

    text = text.strip(" \t\n\r\v\f")
    if not text:
        raise ValueError("duration must not be empty")

    term = re.compile(r"(?:[0-9]+(?:\.[0-9]+)?|\.[0-9]+)(?:ms|[smhd])")
    factors = {"ms": 1, "s": 1000, "m": 60000, "h": 3600000, "d": 86400000}
    total = 0.0
    pos = 0
    while pos < len(text):
        if text[pos] in " \t\n\r\v\f":
            pos += 1
            continue
        match = term.match(text, pos)
        if match is None:
            raise ValueError("invalid duration")
        token = match.group()
        unit = "ms" if token.endswith("ms") else token[-1]
        number = token[:-len(unit)]
        total += float(number) * factors[unit]
        pos = match.end()

    return math.ceil(total)

